ition-plan-checkin" :disabled="busy || day.date > today || isChecked(day.date, meal.meal_type)" :aria-disabled="busy || day.date > today || isChecked(day.date, meal.meal_type)" @click="checkin(day.date, meal.meal_type)">{{ nt(isChecked(day.date, meal.meal_type) ? 'checkedIn' : day.date > today ? 'futureMeal' : 'planCheckin') }}</button></view></view><button role="button" tabindex="0" v-if="['draft', 'archived'].includes(plan.status)" class="nutrition-primary nutrition-plan-activate" :disabled="busy || profileDirty" :aria-disabled="busy || profileDirty" @click="activatePlan">{{ nt('activate') }}</button></view>
      <view v-if="plans.length" class="nutrition-panel"><text class="nutrition-section-title">{{ nt('viewPlan') }}</text><button role="button" tabindex="0" v-for="item in plans" :key="item.id" class="nutrition-plan-history" :disabled="busy || planWorking" :aria-disabled="busy || planWorking" @click="selectPlan(item.id)"><text>{{ item.proposal?.title || nt(item.style || 'plans') }}</text><text>{{ nt(item.status) }}</text></button></view><view v-else-if="!plan" class="nutrition-panel"><text class="nutrition-hint">{{ nt('noPlans') }}</text></view>
    </view>

    <view v-if="status.quota" class="nutrition-panel nutrition-quota"><view class="nutrition-row"><text class="nutrition-section-title">{{ nt('quota') }}</text><button role="button" tabindex="0" class="nutrition-link" :disabled="quotaBusy" :aria-disabled="quotaBusy" @click="refreshStatus().catch(fail)">{{ nt('refresh') }}</button></view><text>{{ nt('quotaRemaining') }}：<text class="nutrition-quota-number">{{ status.quota.remaining }} / {{ status.quota.limit }}</text></text><text v-if="status.quota.next_restore_at" class="nutrition-hint">{{ nt('quotaRestore') }}：{{ quotaTime(status.quota.next_restore_at) }}</text><text class="nutrition-hint">{{ nt('quotaHint') }}</text><text v-if="!status.configured" class="nutrition-warning">{{ nt('unconfigured') }}</text></view>

    <view v-if="mealOpen" class="nutrition-overlay"><view class="nutrition-dialog nutrition-meal-dialog"><view class="nutrition-dialog-header"><text class="nutrition-section-title">{{ nt(editingMeal ? 'editMeal' : 'newMeal') }}</text><button role="button" tabindex="0" class="nutrition-link" :disabled="busy" :aria-disabled="busy" @click="closeMeal">{{ nt('close') }}</button></view><scroll-view scroll-y class="nutrition-dialog-scroll"><view class="nutrition-dialog-body"><text v-if="dialogError" class="nutrition-warning" role="alert">{{ nt(dialogError) }}</text><text class="nutrition-hint">{{ mealDate }}</text><view class="nutrition-field"><text>{{ nt('mealType') }}</text><view class="nutrition-choices"><button role="button" tabindex="0" v-for="type in mealTypes" :key="type" :class="{selected: mealForm.meal_type === type}" :disabled="busy || analyzing || !!editingMeal?.plan_id" :aria-disabled="busy || analyzing || !!editingMeal?.plan_id" @click="mealForm.meal_type = type">{{ nt(type) }}</button></view></view>
      <view v-if="!editingMeal" class="nutrition-photo-input"><view class="nutrition-actions"><button role="button" tabindex="0" class="nutrition-secondary nutrition-photo-album" :disabled="busy || analyzing" :aria-disabled="busy || analyzing" @click="chooseImage('album')">{{ nt('album') }}</button><button role="button" tabindex="0" class="nutrition-secondary nutrition-photo-camera" :disabled="busy || analyzing" :aria-disabled="busy || analyzing" @click="chooseImage('camera')">{{ nt('camera') }}</button></view><text class="nutrition-hint">{{ nt('imageHint') }}</text><image v-if="imagePreview" class="nutrition-photo-preview" :src="imagePreview" mode="aspectFit" /><view v-if="imagePreview"><text v-if="!status.configured" class="nutrition-warning">{{ nt('unconfigured') }}</text><text v-if="status.quota" class="nutrition-hint">{{ nt('quotaRemaining') }}：{{ status.quota.remaining }} / {{ status.quota.limit }}<text v-if="status.quota.next_restore_at"> · {{ nt('quotaRestore') }}：{{ quotaTime(status.quota.next_restore_at) }}</text></text><view class="nutrition-field"><text>{{ nt('description') }}</text><textarea v-model="description" maxlength="500" :placeholder="nt('descriptionHint')" :disabled="busy || analyzing" :aria-disabled="busy || analyzing" /></view><button role="button" tabindex="0" class="nutrition-toggle nutrition-photo-consent" :aria-pressed="photoConsent" :disabled="busy || analyzing" :aria-disabled="busy || analyzing" @click="photoConsent = !photoConsent"><text class="nutrition-checkbox" :class="{checked: photoConsent}">{{ photoConsent ? '✓' : '' }}</text><text>{{ nt('photoConsent') }}</text></button><button role="button" tabindex="0" class="nutrition-primary nutrition-recognize" :disabled="!canAnalyze" :aria-disabled="!canAnalyze" @click="recognize">{{ nt(analyzing ? 'analyzing' : 'recognize') }}</button><view v-if="analysis"><button role="button" tabindex="0" class="nutrition-link nutrition-analysis-refresh" @click="pollAnalysis()">{{ nt('refreshResult') }}</button><text v-if="analysis.summary" class="nutrition-hint">{{ analysis.summary }}</text><text v-for="(warning, i) in analysis.warnings || []" :key="i" class="nutrition-warning">{{ warning }}</text><text v-if="analysis.error_code" class="nutrition-warning">{{ nt(analysis.error_code) }}</text></view><text class="nutrition-hint">{{ nt('estimateHint') }}</text></view></view>
      <text v-if="imagePreview && analysis?.status !== 'ready'" class="nutrition-hint">{{ nt('unattachedPhoto') }}</text><text class="nutrition-hint">{{ nt('manualHint') }}</text><view v-for="(food, index) in mealForm.foods" :key="index" class="nutrition-food-editor"><view class="nutrition-row"><text>{{ nt('food') }} {{ index + 1 }}</text><button role="button" tabindex="0" class="nutrition-link nutrition-danger" :disabled="busy || analyzing || mealForm.foods.length <= 1" :aria-disabled="busy || analyzing || mealForm.foods.length <= 1" @click="mealForm.foods.splice(index, 1)">{{ nt('removeFood') }}</button></view><view class="nutrition-field nutrition-food-name"><input v-model="food.name" maxlength="100" :placeholder="nt('foodHint')" :aria-label="nt('food')" :disabled="busy || analyzing" :aria-disabled="busy || analyzing" /></view><view class="nutrition-food-numbers"><view v-for="key in ['grams', ...macroKeys]" :key="key" class="nutrition-field" :class="'nutrition-food-' + key"><text>{{ key === 'grams' ? nt('weight') : nt(key) + ' (' + nt('grams') + ')' }}</text><input v-model="food[key]" type="digit" :aria-label="key === 'grams' ? nt('weight') : nt(key)" :disabled="busy || analyzing" :aria-disabled="busy || analyzing" /></view></view></view><button role="button" tabindex="0" class="nutrition-secondary nutrition-add-food" :disabled="busy || analyzing || mealForm.foods.length >= 20" :aria-disabled="busy || analyzing || mealForm.foods.length >= 20" @click="mealForm.foods.push(emptyFood())">+ {{ nt('addFood') }}</button><view class="nutrition-field"><text>{{ nt('note') }}</text><textarea v-model="mealForm.note" maxlength="500" :placeholder="nt('noteHint')" :disabled="busy || analyzing" :aria-disabled="busy || analyzing" /></view><view class="nutrition-draft-total"><text>{{ nt('total') }}：{{ number(foodTotal(mealForm.foods).kcal) }} {{ nt('kcal') }}</text><text class="nutrition-hint">{{ nt('kcalFormula') }}</text></view></view></scroll-view><view class="nutrition-dialog-footer"><button role="button" tabindex="0" class="nutrition-secondary" :disabled="busy" :aria-disabled="busy" @click="closeMeal">{{ nt('cancel') }}</button><button role="button" tabindex="0" class="nutrition-primary nutrition-meal-save" :disabled="busy || analyzing" :aria-disabled="busy || analyzing" @click="saveMeal">{{ nt(busy ? 'saving' : 'save') }}</button></view></view></view>
    <view v-if="removeMeal" class="nutrition-overlay"><view class="nutrition-confirm-dialog"><text class="nutrition-section-title">{{ nt('confirmRemove') }}</text><text class="nutrition-hint">{{ nt('removeHint') }}</text><text v-if="dialogError" class="nutrition-warning">{{ nt(dialogError) }}</text><view class="nutrition-actions"><button role="button" tabindex="0" class="nutrition-secondary" :disabled="busy" :aria-disabled="busy" @click="removeMeal = null">{{ nt('cancel') }}</button><button role="button" tabindex="0" class="nutrition-primary nutrition-confirm-delete" :disabled="busy" :aria-disabled="busy" @click="deleteMeal">{{ nt('deleteConfirm') }}</button></view></view></view>
    <view v-if="privatePhoto" class="nutrition-overlay" @click="closePhoto"><view class="nutrition-confirm-dialog nutrition-photo-dialog" @click.stop><view class="nutrition-row"><text class="nutrition-section-title">{{ nt('photo') }}</text><button role="button" tabindex="0" class="nutrition-link" @click="closePhoto">{{ nt('close') }}</button></view><image :src="privatePhoto" mode="aspectFit" class="nutrition-private-photo" /></view></view>
  </view>
</template>

<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue';
import { request } from '../lib/api';
import { locale } from '../lib/i18n';
import { nt } from '../lib/nutrition-i18n';
import { chooseNutritionImage, nutritionPhotoPreview } from '../lib/nutrition-image';
const emit = defineEmits(['unauthorized', 'created']);
const today = new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Shanghai', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
const date = ref(today), tab = ref('records'), period = ref('week'), loading = ref(false), busy = ref(false), quotaBusy = ref(false), error = ref(''), dialogError = ref('');
const summary = ref<any>(null), meals = ref<any[]>([]), stats = ref<any>(null), status = ref<any>({configured:false}), profileOpen = ref(false), savedProfile = ref<any>(null), profileSaved = ref(false), profileSignature = ref('');
const profileDefaults = () => ({age:'',height_cm:'',weight_kg:'',sex:'',goal:'maintain',activity_level:'sedentary',allergies:'',preferences:'',has_conditions:false});
const profileForm = ref<any>(profileDefaults());
const profileDirty = computed(() => !!savedProfile.value && JSON.stringify(profileForm.value) !== profileSignature.value);
const macroKeys = ['carbs_g','protein_g','fat_g']; const mealTypes = ['breakfast','lunch','dinner','snack'];
const validBalance = computed(() => summary.value?.has_records && summary.value?.balance_kcal != null && summary.value?.bmr_kcal != null);
const balanceLabel = computed(() => !validBalance.value ? 'balance' : Number(summary.value.balance_kcal) > 0 ? 'deficit' : Number(summary.value.balance_kcal) < 0 ? 'surplus' : 'even');
const chartMax = computed(() => Math.max(100, Math.ceil(Math.max(...(stats.value?.series || []).map((p:any) => Number(p.intake_kcal)||0),0) / 100) * 100));
const mealOpen = ref(false), editingMeal = ref<any>(null), mealDate = ref(today), removeMeal = ref<any>(null), privatePhoto = ref('');
const emptyFood = () => ({name:'',grams:'100',carbs_g:'0',protein_g:'0',fat_g:'0'});
const mealForm = ref<any>({meal_type:'breakfast',foods:[emptyFood()],note:''});
const imageData = ref(''), imagePreview = ref(''), description = ref(''), photoConsent = ref(false), analysis = ref<any>(null);
const analyzing = computed(() => analysis.value && ['queued','running'].includes(analysis.value.status));
const canAnalyze = computed(() => !!imageData.value && photoConsent.value && !busy.value && !analyzing.value && status.value.configured && status.value.quota?.remaining > 0);
const plans = ref<any[]>([]), plan = ref<any>(null), planStyle = ref('easy'), startDate = ref(today), planConsent = ref(false), checked = ref<string[]>([]);
const planWorking = computed(() => plan.value && ['queued','running'].includes(plan.value.status));
const canPlan = computed(() => savedProfile.value && !profileForm.value.has_conditions && !profileDirty.value && planConsent.value && !busy.value && !planWorking.value && status.value.configured && status.value.quota?.remaining > 0);
let disposed = false, loadSequence = 0, analysisTimer: ReturnType<typeof setTimeout>|undefined, planTimer: ReturnType<typeof setTimeout>|undefined, quotaTimer: ReturnType<typeof setInterval>|undefined;
const requestKeys = new Map<string,string>();
function uuid() { return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,c=> {const n=Math.floor(Math.random()*16);return(c==='x'?n:(n&3)|8).toString(16);}); }
function keyFor(body:any) { const signature=JSON.stringify(body);if(!requestKeys.has(signature))requestKeys.set(signature,uuid());return requestKeys.get(signature); }
function accepted(body:any){requestKeys.delete(JSON.stringify(body));}
function fail(e:any) { error.value=e?.message||'error';if(error.value==='UNAUTHORIZED')emit('unauthorized'); }
function dialogFail(e:any) { dialogError.value=e?.message||'error';if(dialogError.value==='UNAUTHORIZED')emit('unauthorized'); }
function number(value:any, decimals=0) { const n=Number(value);return (Number.isFinite(n)?n:0).toLocaleString(locale.value==='en'?'en-US':'zh-CN',{maximumFractionDigits:decimals}); }
function foodKcal(food:any) { return (Number(food.carbs_g)||0)*4+(Number(food.protein_g)||0)*4+(Number(food.fat_g)||0)*9; }
function foodTotal(foods:any[] = []) { return foods.reduce((total,food)=>({kcal:total.kcal+foodKcal(food),carbs_g:total.carbs_g+(Number(food.carbs_g)||0),protein_g:total.protein_g+(Number(food.protein_g)||0),fat_g:total.fat_g+(Number(food.fat_g)||0)}),{kcal:0,carbs_g:0,protein_g:0,fat_g:0}); }
function macroPercent(key:string) {const weights:any={carbs_g:4,protein_g:4,fat_g:9};const total=macroKeys.reduce((n,k)=>n+(Number(summary.value?.[k])||0)*weights[k],0);return total?Number(summary.value?.[key]||0)*weights[key]/total*100:0;}
function quotaTime(value:string) {return new Intl.DateTimeFormat(locale.value==='en'?'en-US':'zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(value))+' (UTC+8)';}
function chartLabel(point:any) {if(mealTypes.includes(point.label))return nt(point.label);if(period.value==='day')return point.label;return String(point.date||point.label).slice(5);}
function isValidDate(value:string) {return /^\d{4}-\d{2}-\d{2}$/.test(value)&&!Number.isNaN(Date.parse(value+'T12:00:00Z'))&&new Date(value+'T12:00:00Z').toISOString().slice(0,10)===value;}
function moveDate(amount:number) {const d=new Date(date.value+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+amount);void changeDate(d.toISOString().slice(0,10));}
async function changeDate(value:string) {if(!isValidDate(value)){error.value='invalidDate';return;}date.value=value;await loadDay();}
async function loadDay() {const sequence=++loadSequence;loading.value=true;try {const [s,m,c]=await Promise.all([request('/api/nutrition/summary?date='+date.value),request('/api/nutrition/meals?date='+date.value),request('/api/nutrition/stats?period='+period.value+'&date='+date.value)]);if(disposed||sequence!==loadSequence)return;summary.value=s;meals.value=Array.isArray(m)?m:m.meals||[];stats.value=c;}catch(e){if(sequence===loadSequence)fail(e);}finally{if(sequence===loadSequence)loading.value=false;}}
async function setPeriod(value:string) {period.value=value;await loadDay();}
async function refreshStatus() {if(quotaBusy.value||disposed)return;quotaBusy.value=true;try {const s=await request('/api/nutrition/status');if(!disposed)status.value=s;}finally{quotaBusy.value=false;}}
function setProfile(profile:any) {savedProfile.value=profile;profileForm.value=profile?{...profileDefaults(),...Object.fromEntries(Object.keys(profileDefaults()).map(k=>[k,profile[k]])),age:String(profile.age),height_cm:String(profile.height_cm),weight_kg:String(profile.weight_kg)}:profileDefaults();profileSignature.value=JSON.stringify(profileForm.value);}
async function initialize() {error.value='';try {const [profile,,history]=await Promise.all([request('/api/nutrition/profile'),refreshStatus(),request('/api/nutrition/plans')]);if(disposed)return;setProfile(profile);plans.value=Array.isArray(history)?history:history.plans||[];plan.value=plans.value[0]||null;if(!profile){const health=await request('/api/health-profile');if(health)for(const k of ['age','height_cm','weight_kg'])profileForm.value[k]=String(health[k]??'');profileOpen.value=true;}if(planWorking.value)void pollPlan();await loadDay();}catch(e){fail(e);}}
async function saveProfile() {profileSaved.value=false;error.value='';const p={...profileForm.value,age:Number(profileForm.value.age),height_cm:Number(profileForm.value.height_cm),weight_kg:Number(profileForm.value.weight_kg)};if(!Number.isInteger(p.age)||!Number.isFinite(p.height_cm)||!Number.isFinite(p.weight_kg)||p.age<18||p.age>100||p.height_cm<120||p.height_cm>230||p.weight_kg<35||p.weight_kg>300||!['male','female'].includes(p.sex)){error.value='profileValidation';return;}busy.value=true;try {setProfile(await request('/api/nutrition/profile','PUT',p));planConsent.value=false;await loadDay();await refreshPlans();plan.value=plans.value.find(p=>p.id===plan.value?.id)||plans.value[0]||null;busy.value=false;profileSaved.value=true;}catch(e){fail(e);}finally{busy.value=false;}}
function openMeal(meal?:any) {dialogError.value='';editingMeal.value=meal||null;mealDate.value=meal?.date||date.value;mealForm.value={meal_type:meal?.meal_type||'breakfast',note:meal?.note||'',foods:meal?.foods?.map((f:any)=>({name:f.name,grams:String(f.grams),carbs_g:String(f.carbs_g),protein_g:String(f.protein_g),fat_g:String(f.fat_g)}))||[emptyFood()]};imageData.value='';imagePreview.value='';description.value='';photoConsent.value=false;analysis.value=null;mealOpen.value=true;}
async function discardAnalysis(){if(analysis.value?.id)await request('/api/nutrition/analyses/'+analysis.value.id,'DELETE');}
async function closeMeal(){if(busy.value)return;busy.value=true;if(analysisTimer)clearTimeout(analysisTimer);try{await discardAnalysis();mealOpen.value=false;imageData.value='';imagePreview.value='';analysis.value=null;dialogError.value='';}catch(e){dialogFail(e);}finally{busy.value=false;}}
async function chooseImage(source:'album'|'camera') {dialogError.value='';busy.value=true;try {const chosen=await chooseNutritionImage(source);if(!chosen||disposed)return;await discardAnalysis();imageData.value=chosen.imageData;imagePreview.value=chosen.preview;analysis.value=null;photoConsent.value=false;}catch(e){dialogFail(e);}finally{busy.value=false;}}
async function recognize() {if(!canAnalyze.value)return;busy.value=true;dialogError.value='';try {if(analysis.value?.id){await discardAnalysis();analysis.value=null;}const body={image_data:imageData.value,description:description.value.trim(),locale:locale.value,consent:true};analysis.value=await request('/api/nutrition/analyses','POST',{...body,request_key:keyFor(body)});accepted(body);photoConsent.value=false;void pollAnalysis();await refreshStatus().catch(()=>{});}catch(e){dialogFail(e);void refreshStatus().catch(()=>{});}finally{busy.value=false;}}
async function pollAnalysis() {if(analysisTimer)clearTimeout(analysisTimer);if(disposed||!analysis.value)return;const id=analysis.value.id;try {const a=await request('/api/nutrition/analyses/'+id);if(disposed||analysis.value?.id!==id)return;analysis.value=a;if(a.status==='ready'){if(a.foods?.length)mealForm.value.foods=a.foods.map((f:any)=>({name:f.name,grams:String(f.grams),carbs_g:String(f.carbs_g),protein_g:String(f.protein_g),fat_g:String(f.fat_g)}));await refreshStatus();return;}if(a.status==='failed'){await refreshStatus();return;}analysisTimer=setTimeout(pollAnalysis,1800);}catch(e){dialogFail(e);}}
function cleanFoods(){return mealForm.value.foods.map((f:any)=>({name:f.name.trim(),grams:Number(f.grams),carbs_g:Number(f.carbs_g),protein_g:Number(f.protein_g),fat_g:Number(f.fat_g)}));}
async function saveMeal() {dialogError.value='';if(!isValidDate(mealDate.value)||mealDate.value>today){dialogError.value='noFuture';return;}const foods=cleanFoods();if(!foods.length||foods.some((f:any)=>!f.name||!Number.isFinite(f.grams)||f.grams<=0||f.grams>2000||macroKeys.some(k=>!Number.isFinite(f[k])||f[k]<0||f[k]>500)||f.carbs_g+f.protein_g+f.fat_g>f.grams+0.5)){dialogError.value='validation';return;}busy.value=true;try {const body:any={meal_type:mealForm.value.meal_type,foods,note:mealForm.value.note.trim()};if(editingMeal.value)await request('/api/nutrition/meals/'+editingMeal.value.id,'PATCH',body);else {body.date=mealDate.value;if(analysis.value?.status==='ready')body.analysis_id=analysis.value.id;await request('/api/nutrition/meals','POST',{...body,request_key:keyFor(body)});accepted(body);}if(analysis.value?.id&&analysis.value.status!=='ready')await discardAnalysis().catch(()=>{});mealOpen.value=false;imageData.value='';imagePreview.value='';await loadDay();emit('created');}catch(e){dialogFail(e);}finally{busy.value=false;}}
async function deleteMeal(){busy.value=true;dialogError.value='';try {await request('/api/nutrition/meals/'+removeMeal.value.id,'DELETE');const deleted=removeMeal.value;removeMeal.value=null;checked.value=checked.value.filter(k=>k!==deleted.plan_id+'/'+deleted.date+'/'+deleted.meal_type);if(plan.value?.id===deleted.plan_id)plan.value.checkins=(plan.value.checkins||[]).filter((c:any)=>!(c.date===deleted.date&&c.meal_type===deleted.meal_type));await loadDay();emit('created');}catch(e){dialogFail(e);}finally{busy.value=false;}}
let releasePhoto=()=>{};
function closePhoto(){releasePhoto();releasePhoto=()=>{};privatePhoto.value='';}
async function viewPhoto(id:string){busy.value=true;error.value='';try {const p=await request('/api/nutrition/photos/'+id);if(!p.image_data)throw new Error('photoUnavailable');const preview=await nutritionPhotoPreview(p.image_data);if(disposed){preview.release();return;}closePhoto();releasePhoto=preview.release;privatePhoto.value=preview.preview;}catch(e){fail(e);}finally{busy.value=false;}}
async function refreshPlans(){const h=await request('/api/nutrition/plans');if(!disposed)plans.value=Array.isArray(h)?h:h.plans||[];}
async function generatePlan(){if(!canPlan.value)return;busy.value=true;error.value='';try {const body={style:planStyle.value,start_date:startDate.value,locale:locale.value,consent:true};plan.value=await request('/api/nutrition/plans/generate','POST',{...body,request_key:keyFor(body)});accepted(body);planConsent.value=false;void pollPlan();await refreshStatus().catch(()=>{});}catch(e){fail(e);void refreshStatus().catch(()=>{});}finally{busy.value=false;}}
async function pollPlan(){if(planTimer)clearTimeout(planTimer);if(disposed||!plan.value)return;const id=plan.value.id;try {const p=await request('/api/nutrition/plans/'+id);if(disposed||plan.value?.id!==id)return;plan.value=p;if(!['queued','running'].includes(p.status)){await Promise.all([refreshPlans(),refreshStatus()]);return;}planTimer=setTimeout(pollPlan,1800);}catch(e){fail(e);}}
let selectionSequence=0;
async function selectPlan(id:string){error.value='';if(planTimer)clearTimeout(planTimer);const sequence=++selectionSequence;try {const selected=await request('/api/nutrition/plans/'+id);if(disposed||sequence!==selectionSequence)return;plan.value=selected;if(planWorking.value)void pollPlan();}catch(e){fail(e);}}
async function activatePlan(){busy.value=true;error.value='';try {plan.value=await request('/api/nutrition/plans/'+plan.value.id+'/activate','POST',{confirm:true});await refreshPlans();}catch(e){fail(e);}finally{busy.value=false;}}
function isChecked(day:string,type:string){return checked.value.includes(plan.value?.id+'/'+day+'/'+type)||(plan.value?.checkins||[]).some((c:any)=>c.date===day&&c.meal_type===type)||meals.value.some(m=>(m.nutrition_plan_id||m.plan_id)===plan.value?.id&&m.date===day&&m.meal_type===type);}
async function checkin(day:string,type:string){if(day>today||isChecked(day,type))return;busy.value=true;error.value='';try {const body={date:day,meal_type:type};await request('/api/nutrition/plans/'+plan.value.id+'/checkins','POST',{...body,request_key:keyFor({...body,plan_id:plan.value.id})});checked.value.push(plan.value.id+'/'+day+'/'+type);date.value=day;await loadDay();emit('created');}catch(e){fail(e);}finally{busy.value=false;}}
onMounted(()=>{void initialize();quotaTimer=setInterval(()=>{void refreshStatus().catch(()=>{});},30000);});
onUnmounted(()=>{disposed=true;closePhoto();if(mealOpen.value&&analysis.value?.id)void discardAnalysis().catch(()=>{});if(analysisTimer)clearTimeout(analysisTimer);if(planTimer)clearTimeout(planTimer);if(quotaTimer)clearInterval(quotaTimer);});
</script>

